import React from "react";
import "./SOSButton.css";

const SOSButton = () => {
  const playSiren = () => {
    const audio = new Audio("siren.mp3");
    audio.play();
    alert("🚨 SOS Activated! Emergency services alerted.");
  };

  return (
    <button className="sos-btn" onClick={playSiren}>
      SOS
    </button>
  );
};

export default SOSButton;
